# Rebuild docs/ARTIFACT-AND-VERSION-REPORT.md from GitHub Actions artifacts.
$ErrorActionPreference = "Stop"
$repo = $env:GITHUB_REPOSITORY
$token = $env:GITHUB_TOKEN
if ([string]::IsNullOrWhiteSpace($repo) -or [string]::IsNullOrWhiteSpace($token)) {
  throw "GITHUB_REPOSITORY and GITHUB_TOKEN are required."
}
$headers = @{
  Authorization = "Bearer $token"
  Accept = "application/vnd.github+json"
  "X-GitHub-Api-Version" = "2022-11-28"
}
$artifacts = @()
$page = 1
do {
  $response = Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/actions/artifacts?per_page=100&page=$page" -Headers $headers
  $batch = @($response.artifacts)
  $artifacts += $batch
  $page++
} while ($batch.Count -eq 100)

$lines = [System.Collections.Generic.List[string]]::new()
$lines.Add("# GTMC CBT – Artifact & Version Report")
$lines.Add("")
$lines.Add("> Automatically refreshed from GitHub Actions artifact records after successful builds on the main branch.")
$lines.Add("")
$lines.Add("## How to choose")
$lines.Add("")
$lines.Add("| What you need | Choose |")
$lines.Add("|---|---|")
$lines.Add("| First-time Admin installation | `GTMC-CBT-Admin-Fresh-Installation-Windows.exe` inside the latest three-installer package |")
$lines.Add("| First-time Examination installation | `GTMC-CBT-Examination-Fresh-Installation-Windows.exe` inside the latest three-installer package |")
$lines.Add("| Update an existing installation | `GTMC-CBT-Complete-Update-Windows.exe` inside the latest three-installer package |")
$lines.Add("| Diagnose a problem | Matching Admin or Examination Diagnostic utility |")
$lines.Add("| Restore a backup | `GTMC-CBT-Restore-Windows.exe` |")
$lines.Add("| Android testing | Matching Android debug APK; not for Windows |")
$lines.Add("")
$lines.Add("## Build artifacts")
$lines.Add("")
$lines.Add("| Created (UTC) | Artifact | Size | Availability | Download / build |")
$lines.Add("|---|---|---:|---|---|")

$sorted = @($artifacts | Sort-Object -Property created_at -Descending)
foreach ($artifact in $sorted) {
  $created = ([datetime]$artifact.created_at).ToUniversalTime().ToString("yyyy-MM-dd HH:mm")
  $size = "{0:N0} bytes" -f [double]$artifact.size_in_bytes
  $availability = if ($artifact.expired) { "Expired" } else { "Available" }
  $artifactUrl = "https://github.com/$repo/actions/artifacts/$($artifact.id)"
  $runUrl = "https://github.com/$repo/actions/runs/$($artifact.workflow_run.id)"
  $link = "[Artifact #$($artifact.id)]($artifactUrl) · [Build run]($runUrl)"
  $safeName = ([string]$artifact.name).Replace("|","\|")
  $lines.Add("| $created | $safeName | $size | $availability | $link |")
}
if ($sorted.Count -eq 0) {
  $lines.Add("| — | No artifacts returned by GitHub yet | — | — | — |")
}
$lines.Add("")
$historyPath = "docs/PROJECT-HISTORY.md"
if (Test-Path $historyPath) {
  $historyContent = [System.IO.File]::ReadAllText((Join-Path (Get-Location) $historyPath), [System.Text.Encoding]::UTF8)
  foreach ($historyLine in ($historyContent -split "`r?`n")) {
    $lines.Add($historyLine)
  }
}
$lines.Add("")
$lines.Add("## Important notes")
$lines.Add("")
$lines.Add("- GitHub Actions artifact downloads are governed by repository retention settings and can expire; expired entries remain listed when GitHub returns their metadata.")
$lines.Add("- A GitHub artifact is downloaded as a ZIP. Open it to access the installer or utility inside.")
$lines.Add("- The combined three-installer package size is not the running application's RAM usage.")
$lines.Add("- The desktop runtime is Electron with bundled Chromium; WebView2 is not used.")
$lines.Add("- Automated build success does not prove Windows Server 2016 compatibility, actual RAM savings or support for 50 simultaneous RDP sessions. Those require staged tests on a separate test server.")
$lines.Add("")
$lines.Add("_Generated by .github/scripts/update-artifact-report.ps1._")

$path = "docs/ARTIFACT-AND-VERSION-REPORT.md"
$content = ($lines -join "`n") + "`n"
$directory = Split-Path -Parent $path
New-Item -ItemType Directory -Force -Path $directory | Out-Null
[System.IO.File]::WriteAllText((Join-Path (Get-Location) $path), $content, [System.Text.UTF8Encoding]::new($false))
Write-Host "Updated $path with $($sorted.Count) artifact records."
